    "astrology.planet.meaning.uranus": "Yenilik ve \xD6zg\xFCrl\xFCk",
    "astrology.planet.meaning.venus": "Sevgi ve De\u011Ferler",
    "astrology.planet.sun.desc": "Ki\u015Fili\u011Finizin \xE7ekirde\u011Fini, temel iradenizi ve egonuzu temsil eder. Hayat yolculu\u011Funuzda parlad\u0131\u011F\u0131n\u0131z ve 'ben buraday\u0131m' dedi\u011Finiz merkezdir.",
    "astrology.planet.sun.traits.pos": "Liderlik, yarat\u0131c\u0131l\u0131k, c\xF6mertlik, \xF6zg\xFCven.",
    "astrology.planet.sun.traits.neg": "Bencillik, kibir, otoriterlik, a\u015F\u0131r\u0131 gurur.",
    "astrology.planet.moon.desc": "Duygusal ihtiya\xE7lar\u0131n\u0131z\u0131, al\u0131\u015Fkanl\u0131klar\u0131n\u0131z\u0131 ve i\xE7 d\xFCnyan\u0131z\u0131 y\xF6netir. Nas\u0131l hissetti\u011Finiz ve nas\u0131l g\xFCvende hissetmek istedi\u011Finizle ilgilidir.",
    "astrology.planet.moon.traits.pos": "Empati, \u015Fefkat, duyarl\u0131l\u0131k, hayal g\xFCc\xFC.",
    "astrology.planet.moon.traits.neg": "A\u015F\u0131r\u0131 duygusall\u0131k, karars\u0131zl\u0131k, k\u0131r\u0131lganl\u0131k.",
    "astrology.planet.mercury.desc": "D\xFC\u015F\xFCnce tarz\u0131n\u0131z\u0131, ileti\u015Fim yetene\u011Finizi ve zihinsel s\xFCre\xE7lerinizi temsil eder. Bilgiyi nas\u0131l i\u015Fledi\u011Finizi g\xF6sterir.",
    "astrology.planet.mercury.traits.pos": "Mant\u0131k, hitabet, analiz yetene\u011Fi, merak.",
    "astrology.planet.mercury.traits.neg": "Kurnazl\u0131k, karars\u0131zl\u0131k, zihinsel da\u011F\u0131n\u0131kl\u0131k.",
    "astrology.planet.venus.desc": "Sevgi anlay\u0131\u015F\u0131n\u0131z\u0131, de\u011Ferlerinizi ve estetik zevkinizi y\xF6netir. Neyi sevdi\u011Finizi ve neye de\u011Fer verdi\u011Finizi anlat\u0131r.",
    "astrology.planet.venus.traits.pos": "Diplomasi, sanat\xE7\u0131 ruh, sevgi dolu, \xE7ekicilik.",
    "astrology.planet.venus.traits.neg": "Tembellik, y\xFCzeysellik, a\u015F\u0131r\u0131 l\xFCks tutkusu.",
    "astrology.planet.mars.desc": "Enerjinizi, eylem g\xFCc\xFCn\xFCz\xFC ve hayattaki itici g\xFCc\xFCn\xFCz\xFC temsil eder. \u0130stedi\u011Finizi almak i\xE7in nas\u0131l sava\u015Ft\u0131\u011F\u0131n\u0131z\u0131 g\xF6sterir.",
    "astrology.planet.mars.traits.pos": "Cesaret, inisiyatif, fiziksel dayan\u0131kl\u0131l\u0131k, h\u0131rs.",
    "astrology.planet.mars.traits.neg": "Sald\u0131rganl\u0131k, sab\u0131rs\u0131zl\u0131k, d\xFCrt\xFCsellik.",
    "astrology.planet.jupiter.desc": "B\xFCy\xFCmeyi, bollu\u011Fu, \u015Fans\u0131 ve hayat felsefenizi y\xF6netir. Nerede \u015Fansl\u0131 oldu\u011Funuzu ve nas\u0131l geni\u015Fledi\u011Finizi anlat\u0131r.",
    "astrology.planet.jupiter.traits.pos": "\u0130yimserlik, c\xF6mertlik, bilgelik, ho\u015Fg\xF6r\xFC.",
    "astrology.planet.jupiter.traits.neg": "A\u015F\u0131r\u0131ya ka\xE7ma, savurganl\u0131k, dogmatik tutumlar.",
    "astrology.planet.saturn.desc": "S\u0131n\u0131rlar\u0131, sorumluluklar\u0131 ve hayat derslerini temsil eder. Disiplin kazand\u0131\u011F\u0131n\u0131z ve yap\u0131land\u0131rd\u0131\u011F\u0131n\u0131z aland\u0131r.",
    "astrology.planet.saturn.traits.pos": "Sab\u0131r, d\xFCr\xFCstl\xFCk, dayan\u0131kl\u0131l\u0131k, ciddiyet.",
    "astrology.planet.saturn.traits.neg": "Kat\u0131l\u0131k, korku, a\u015F\u0131r\u0131 ele\u015Ftirellik, melankoli.",
    "astrology.planet.uranus.desc": "Ani de\u011Fi\u015Fimleri, \xF6zg\xFCrl\xFC\u011F\xFC ve toplumsal normlar\u0131n d\u0131\u015F\u0131na \xE7\u0131kmay\u0131 temsil eder. Dehan\u0131z\u0131n ve isyan\u0131n\u0131z\u0131n kayna\u011F\u0131d\u0131r.",
    "astrology.planet.uranus.traits.pos": "Yenilik\xE7ilik, \xF6zg\xFCnl\xFCk, ba\u011F\u0131ms\u0131zl\u0131k, ilerici d\xFC\u015F\xFCnce.",
    "astrology.planet.uranus.traits.neg": "Asilik, dengesizlik, ani kopu\u015Flar, tuhafl\u0131k.",
    "astrology.planet.neptune.desc": "Spirit\xFCelli\u011Fi, hayalleri ve ilham\u0131 y\xF6netir. S\u0131n\u0131rlar\u0131n kalkt\u0131\u011F\u0131 ve birlik bilincine ula\u015F\u0131ld\u0131\u011F\u0131 aland\u0131r.",
    "astrology.planet.neptune.traits.pos": "Sezgi, ilham, fedakarl\u0131k, ruhsal derinlik.",
    "astrology.planet.neptune.traits.neg": "Kafa kar\u0131\u015F\u0131kl\u0131\u011F\u0131, ka\xE7\u0131\u015F e\u011Filimi, kurban bilinci.",
    "astrology.planet.pluto.desc": "D\xF6n\xFC\u015F\xFCm\xFC, \xF6l\xFCm\xFC ve yeniden do\u011Fu\u015Fu temsil eder. Derin g\xFC\xE7lerin ve krizlerle gelen evrimin merkezidir.",
    "astrology.planet.pluto.traits.pos": "Yenilenme, derinlik, sars\u0131lmaz irade, karizma.",
    "astrology.planet.pluto.traits.neg": "Manip\xFClasyon, obsesyon, y\u0131k\u0131m arzusu.",
