    "astrology.moon.phase.balsamic": "\u0642\u0645\u0631 \u0628\u0644\u0633\u0645\u064A",
    "astrology.moon.phase.balsamic.desc": "\u0648\u0642\u062A \u0627\u0644\u0631\u0627\u062D\u0629 \u0648\u0627\u0644\u0627\u0633\u062A\u0633\u0644\u0627\u0645 \u0648\u0627\u0644\u0625\u063A\u0644\u0627\u0642 \u0627\u0644\u0631\u0648\u062D\u064A \u0642\u0628\u0644 \u0627\u0644\u062A\u062C\u062F\u064A\u062F.",
    "astrology.moon.phase.crescent": "\u0647\u0644\u0627\u0644 \u0645\u062A\u0632\u0627\u064A\u062F",
    "astrology.moon.phase.crescent.desc": "\u0645\u0631\u062D\u0644\u0629 \u062A\u0641\u0639\u064A\u0644 \u0646\u0648\u0627\u064A\u0627\u0643 \u0648\u0627\u062A\u062E\u0627\u0630 \u0627\u0644\u062E\u0637\u0648\u0627\u062A \u0627\u0644\u0623\u0648\u0644\u0649.",
    "astrology.moon.phase.disseminating": "\u0623\u062D\u062F\u0628 \u0645\u062A\u0646\u0627\u0642\u0635",
    "astrology.moon.phase.disseminating.desc": "\u0648\u0642\u062A \u0645\u0634\u0627\u0631\u0643\u0629 \u0627\u0644\u062D\u0643\u0645\u0629 \u0648\u0627\u0644\u0634\u0643\u0631 \u0648\u062A\u0642\u064A\u064A\u0645 \u0627\u0644\u0625\u0646\u062C\u0627\u0632\u0627\u062A.",
    "astrology.moon.phase.first_quarter": "\u0627\u0644\u062A\u0631\u0628\u064A\u0639 \u0627\u0644\u0623\u0648\u0644",
